11	ExtractFuncInfo(const IRModule &mod) {
12	  std::unordered_map<std::string, runtime::FunctionInfo> fmap;
13	
14	  for (auto kv : mod->functions) {
15	    ICHECK(kv.second->IsInstance<tir::PrimFuncNode>())
16	        << "Can only lower IR Module with PrimFuncs";
17	    auto f = Downcast<tir::PrimFunc>(kv.second);
18	
19	    runtime::FunctionInfo info;
20	    for (size_t i = 0; i < f->params.size(); ++i) {
21	      if (f->params[i]->dtype.is_handle()) {
