23	        if (ptr && ptr->storage_scope == "grid_constant") {
24	          info.arg_types.push_back(DataType(runtime::kDLGridConstant, 64, 1));
25	          continue;
26	        }
27	      }
28	      DataType dtype = f->params[i].dtype();
29	      // Device runtime cannot directly take bool arguments, map to int32.
30	      if (dtype.is_bool())
31	        dtype = DataType::Int(32);
32	      info.arg_types.push_back(dtype);
33	    }
34	    if (auto opt = f->GetAttr<ffi::Array<ffi::String>>(
35	            tir::attr::kKernelLaunchParams)) {
36	      for (const auto &tag : opt.value()) {
37	        info.launch_param_tags.push_back(tag);
38	      }
39	    }
40	    auto global_symbol = f->GetAttr<ffi::String>(tvm::attr::kGlobalSymbol);
41	    fmap[static_cast<std::string>(global_symbol.value())] = info;
42	  }
43	  return fmap;
44	}
