47	  bool output_ssa = false;
48	  CodeGenTileLangCUDA cg;
49	  cg.Init(output_ssa);
50	
51	  for (auto kv : mod->functions) {
52	    ICHECK(kv.second->IsInstance<PrimFuncNode>())
53	        << "CodeGenTileLangCUDA: Can only take PrimFunc";
54	    auto gvar = Downcast<GlobalVar>(kv.first);
55	    auto f = Downcast<PrimFunc>(kv.second);
56	    auto calling_conv = f->GetAttr<Integer>(tvm::attr::kCallingConv);
57	    ICHECK(calling_conv == CallingConv::kDeviceKernelLaunch);
58	    cg.AddFunction(gvar, f);
59	  }
60	
61	  std::string code = cg.Finish();
62	  if (const auto f =
63	          ffi::Function::GetGlobal("tilelang_callback_cuda_postproc")) {
64	    code = (*f)(code, target).cast<std::string>();
65	  }
