74	    if (ptx[0] != '/')
75	      fmt = "cubin";
76	  } else {
77	    ICHECK(0);
78	  }
79	  return runtime::TileScaleCUDAModuleCreate(ptx, fmt, ExtractFuncInfo(mod),
