1445	void CodeGenTileLangCUDA::VisitExpr_(const CallNode *op, std::ostream &os) {
1446	  auto print_extern_call_stmt = [&](std::string name, size_t start = 0,
1447	                                    size_t end = 0) {
1448	    // Cache context into a private ss, otherwise the let node may generate
1449	    // within the function call arguments.
1450	    std::ostringstream ss;
1451	
1452	    for (size_t i = start; i < op->args.size() - end; i++) {
1453	      if (i > start)
1454	        ss << ", ";
1455	      ss << this->PrintExpr(op->args[i]);
1456	    }
1457	
1458	    this->PrintIndent();
1459	    this->stream << name << "(";
1460	    this->stream << ss.str();
1461	    this->stream << ");\n";
1462	  };
1463	  auto print_mbarrier_obj = [&](PrimExpr barrier_id) {
1464	    std::ostringstream ss;
1465	    if (barrier_id.as<IntImmNode>()) {
1466	      // incase the barrier_id is an integer, we need to print the barrier_id as
1467	      // an integer
1468	      ss << mbarrier_name_ << "[" << barrier_id << "]";
1469	    } else {
1470	      // otherwise may be a T.get_mbarrier() call or BufferLoad Node
1471	      // we need to print the barrier_id as a string
1472	      ss << this->PrintExpr(barrier_id);
1473	    }
1474	    return ss.str();
1475	  };
1476	  if (op->op.same_as(builtin::ptx_cp_async())) {
1477	    std::string dst = this->PrintExpr(op->args[0]);
1478	    std::string dst_offset = this->PrintExpr(op->args[1]);
1479	    std::string src = this->PrintExpr(op->args[2]);
1480	    std::string src_offset = this->PrintExpr(op->args[3]);
1481	    std::string size = this->PrintExpr(op->args[4]);
1482	    // use size of argument list to indicate whether or not to use predicated
1483	    // cp.async
1484	    if (op->args.size() == 5) {
1485	      this->PrintIndent();
1486	      this->stream << "tl::cp_async_gs<" << size << ">(" << dst << "+"
1487	                   << dst_offset << ", " << src << "+" << src_offset << ");\n";
1488	    } else {
1489	      std::string condition = this->PrintExpr(op->args[5]);
1490	      this->PrintIndent();
1491	      this->stream << "tl::cp_async_gs_conditional<" << size << ">(" << dst
1492	                   << "+" << dst_offset << ", " << src << "+" << src_offset
1493	                   << ", " << condition << ");\n";
1494	    }
1495	  } else if (op->op.same_as(builtin::ptx_commit_group())) {
1496	    print_extern_call_stmt("tl::cp_async_commit");
1497	  } else if (op->op.same_as(builtin::ptx_wait_group())) {
1498	    int n = Downcast<IntImm>(op->args[0])->value;
1499	    std::string func_name = "tl::cp_async_wait<" + std::to_string(n) + ">";
1500	    print_extern_call_stmt(func_name, 1);
1501	  } else if (op->op.same_as(builtin::create_barriers())) {
1502	    this->PrintIndent();
1503	    int barrier_count = Downcast<IntImm>(op->args[0])->value;
1504	    auto mbarrier_storage_name = mbarrier_name_ + "_mem";
1505	    this->stream << "__shared__ uint64_t " << mbarrier_storage_name << "["
1506	                 << barrier_count << "];\n";
1507	    this->PrintIndent();
1508	    this->stream << "auto " << mbarrier_name_ << " = reinterpret_cast<"
1509	                 << mbarrier_dtype_ << "*>(" << mbarrier_storage_name << ");\n";
1510	  } else if (op->op.same_as(tl::get_mbarrier())) {
1511	    ICHECK_EQ(op->args.size(), 1);
1512	    std::string barrier_id = this->PrintExpr(op->args[0]);
1513	    os << mbarrier_name_ + "[" + barrier_id + "]";
1514	  } else if (op->op.same_as(builtin::ptx_arrive_barrier())) {
1515	    if (op->args.size() == 1) {
1516	      this->PrintIndent();
1517	      auto mbarrier_obj = print_mbarrier_obj(op->args[0]);
1518	      this->stream << mbarrier_obj << ".arrive();\n";
1519	    } else if (op->args.size() == 3) {
1520	      this->PrintIndent();
1521	      auto mbarrier_obj = print_mbarrier_obj(op->args[0]);
1522	      auto cta_id = this->PrintExpr(op->args[1]);
1523	      auto pred = this->PrintExpr(op->args[2]);
1524	      this->stream << mbarrier_obj << ".arrive(" << cta_id << ", " << pred
1525	                   << ");\n";
1526	    } else {
1527	      LOG(FATAL) << "Invalid parameter  for tl::arrive_barrier "
1528	                 << op->args.size();
1529	    }
1530	  } else if (op->op.same_as(builtin::ptx_init_barrier_thread_count())) {
1531	    ICHECK_EQ(op->args.size(), 2);
1532	    this->PrintIndent();
1533	    auto mbarrier_obj = print_mbarrier_obj(op->args[0]);
1534	    auto arrive_count = this->PrintExpr(op->args[1]);
1535	    this->stream << mbarrier_obj << ".init(" << arrive_count << ");\n";
1536	  } else if (op->op.same_as(builtin::ptx_arrive_barrier_expect_tx())) {
1537	    if (op->args.size() == 2) {
1538	      this->PrintIndent();
1539	      auto mbarrier_obj = print_mbarrier_obj(op->args[0]);
1540	      auto transaction_bytes = this->PrintExpr(op->args[1]);
1541	      this->stream << mbarrier_obj << ".arrive_and_expect_tx("
1542	                   << transaction_bytes << ");\n";
1543	    } else if (op->args.size() == 4) {
1544	      this->PrintIndent();
1545	      auto mbarrier_obj = print_mbarrier_obj(op->args[0]);
1546	      auto transaction_bytes = this->PrintExpr(op->args[1]);
1547	      auto cta_id = this->PrintExpr(op->args[2]);
1548	      auto pred = this->PrintExpr(op->args[3]);
1549	      this->stream << mbarrier_obj << ".arrive_and_expect_tx("
1550	                   << transaction_bytes << ", " << cta_id << ", " << pred
1551	                   << ");\n";
1552	    } else {
1553	      LOG(FATAL) << "Invalid parameter  for tl::arrive_barrier_expect_tx "
1554	                 << op->args.size();
1555	    }
1556	  } else if (op->op.same_as(builtin::ptx_cp_async_barrier())) {
1557	    print_extern_call_stmt("tl::mbarrier_cp_async_arrive");
1558	  } else if (op->op.same_as(tl::ptx_fence_barrier_init())) {
1559	    print_extern_call_stmt("tl::fence_barrier_init");
1560	  } else if (op->op.same_as(tl::ptx_cp_async_barrier_noinc())) {
1561	    print_extern_call_stmt("tl::mbarrier_cp_async_arrive_noinc");
1562	  } else if (op->op.same_as(tl::mbarrier_expect_tx())) {
1563	    ICHECK_EQ(op->args.size(), 2);
1564	    this->PrintIndent();
