96	void CodeGenTileLangCPP::PrintType(DataType t, std::ostream &os) { // NOLINT(*)
97	  int lanes = t.lanes();
98	  if (t.is_handle()) {
99	    ICHECK_EQ(lanes, 1) << "does not support vector types";
100	    os << "void*";
101	    return;
102	  }
103	  if (t.is_void()) {
104	    os << "void";
105	    return;
106	  }
107	  if (t == DataType::Bool()) {
108	    os << "bool";
109	    return;
110	  }
111	  bool fail = false;
112	  if (t.is_float()) {
113	    switch (t.bits()) {
114	    case 16:
115	      os << "half";
116	      break;
117	    case 32:
118	      os << "float";
119	      break;
120	    case 64:
121	      os << "double";
122	      break;
123	    default:
124	      fail = true;
125	      break;
126	    }
127	    if (!fail && lanes == 1)
128	      return;
129	    if (!fail && (lanes >= 2 && lanes <= 16)) {
130	      os << lanes;
131	      return;
132	    }
133	  } else if (t.is_uint() || t.is_int()) {
134	    if (t.is_uint()) {
135	      os << 'u';
136	    }
137	    switch (t.bits()) {
138	    case 8:
139	      os << "int8_t";
140	      break;
141	    case 16:
142	      os << "int16_t";
143	      break;
144	    case 32:
145	      os << "int32_t";
146	      break;
147	    case 64:
148	      os << "int64_t";
149	      break;
150	    case 1:
151	      os << "int32_t";
152	      break;
153	    default:
154	      fail = true;
155	      break;
156	    }
157	    if (!fail && lanes == 1)
158	      return;
159	    if (!fail && (lanes >= 2 && lanes <= 16)) {
160	      os << lanes;
161	      return;
162	    }
163	  }
164	  LOG(FATAL) << "Cannot convert type " << t << " to C type";
165	}
