171	  os << "((";
172	  PrintType(op->dtype, os);
173	  os << ")(";
174	  for (int i = 0; i < lanes; ++i) {
175	    if (i != 0)
176	      os << ", ";
177	    os << v;
178	  }
179	  os << "))";
180	}
