254	void CodeGenTileLangCPP::AddFunction(const PrimFunc &f) {
255	  // clear previous generated state.
256	  this->InitFuncState(f);
257	  // reserve keywords
258	  ReserveKeywordsAsUnique();
259	
260	  auto global_symbol = f->GetAttr<ffi::String>(tvm::attr::kGlobalSymbol);
261	  ICHECK(global_symbol)
262	      << "CodeGenC: Expect PrimFunc to have the global_symbol attribute";
263	  bool no_alias = f->HasNonzeroAttr(tir::attr::kNoAlias);
264	  std::unordered_set<const VarNode *> non_restrict;
265	  if (auto opt =
266	          f->GetAttr<ffi::Array<tir::Var>>(tl::attr::kNonRestrictParams)) {
267	    for (const tir::Var &v : opt.value())
268	      non_restrict.insert(v.get());
269	  }
270	
271	  this->PrintFuncPrefix(stream);
272	  CodeGenC::PrintType(f->ret_type, stream);
273	  this->PrintExtraAttrs(f, stream);
274	  this->stream << " " << static_cast<std::string>(global_symbol.value()) << "(";
275	
276	  for (size_t i = 0; i < f->params.size(); ++i) {
277	    tir::Var v = f->params[i];
278	    std::string vid = AllocVarID(v.get());
279	    if (i != 0)
280	      stream << ", ";
281	    if (v.dtype().is_handle()) {
282	      // work around for grid constant parameters.
283	      if (auto *ptr = v->type_annotation.as<PointerTypeNode>()) {
284	        if (ptr->storage_scope == "grid_constant") {
285	          stream << "__grid_constant__ const ";
286	          CodeGenC::PrintType(ptr->element_type, stream);
287	          stream << ' ' << vid;
288	          continue;
289	        }
290	      }
291	
292	      auto it = alloc_storage_scope_.find(v.get());
293	      if (it != alloc_storage_scope_.end()) {
294	        PrintStorageScope(it->second, stream);
295	      }
296	
297	      CodeGenC::PrintType(GetType(v), stream);
298	      if (auto *ptr = v->type_annotation.as<PointerTypeNode>()) {
299	        if (auto *prim = ptr->element_type.as<PrimTypeNode>()) {
300	          RegisterHandleType(v.get(), prim->dtype);
301	        }
302	      }
303	
304	      if (no_alias && !non_restrict.count(v.get())) {
305	        PrintRestrict(v, stream);
306	      }
307	    } else {
308	      CodeGenC::PrintType(GetType(v), stream);
309	    }
310	    stream << ' ' << vid;
311	  }
312	  stream << ") {\n";
313	  this->PreFunctionBody(f);
314	  int func_scope = this->BeginScope();
315	  this->PrintStmt(f->body);
316	  this->EndScope(func_scope);
317	  this->PrintIndent();
318	  this->stream << "}\n\n";
319	}
