321	std::string CodeGenTileLangCPP::GetPackedName(const CallNode *op) {
322	  const StringImmNode *s = op->args[0].as<StringImmNode>();
323	  ICHECK(s != nullptr)
324	      << "tvm_call_packed_lowered expects first argument as function name";
325	  std::string func_name = s->value;
326	  std::string packed_func_name = func_name + "_packed";
327	  std::string unique_name;
328	  auto it = declared_globals_.find(packed_func_name);
329	  if (it != declared_globals_.end()) {
330	    unique_name = it->second;
331	  } else {
332	    unique_name = name_supply_->FreshName(packed_func_name);
333	    declared_globals_[packed_func_name] = unique_name;
334	    decl_stream << "static void* " << unique_name << " = NULL;\n";
335	  }
336	  return unique_name;
337	}
338	
339	CodeGenTileLangCPP::FunctionInfo
340	CodeGenTileLangCPP::GetFunctionInfo(const CallNode *op,
341	                                    bool has_resource_handle) {
342	  const StringImmNode *s = op->args[0].as<StringImmNode>();
343	  ICHECK(s != nullptr)
344	      << "tvm_call_[c]packed_lowered expects first argument as function name";
345	  int64_t begin = op->args[3].as<IntImmNode>()->value;
346	  int64_t end = op->args[4].as<IntImmNode>()->value;
347	  int64_t num_args = end - begin;
348	  ICHECK_GE(num_args, 0);
349	  std::string func_name = s->value;
350	
351	  if (has_resource_handle) {
352	    const StringImmNode *resource_handle_var = op->args[5].as<StringImmNode>();
353	    if (resource_handle_var != nullptr) {
354	      std::string resource_handle_name = resource_handle_var->value;
355	      return {func_name, num_args - 1, resource_handle_name};
356	    } else {
357	      // The final arg should be "(void*) NULL" to indicate the empty
358	      // resource_handle.
359	      num_args--;
360	
361	      const CallNode *reinterpret_call = op->args[5].as<CallNode>();
362	      ICHECK_NE(reinterpret_call, (void *)nullptr)
363	          << "At CallNode to " << s
364	          << "arg 5: Expect either StringImm naming the resource_handle var "
365	             "from interface API or "
366	          << "reinterpret(0); got: " << op->args[5];
367	      ICHECK_EQ(reinterpret_call->op, builtin::reinterpret())
368	          << "At CallNode to " << s
369	          << "arg 5: Expect either StringImm naming the resource_handle var "
370	             "from interface API or "
371	          << "reinterpret(0); got: " << op->args[5];
372	      ICHECK(is_zero(reinterpret_call->args[0]))
373	          << "At CallNode to " << s
374	          << " arg 5: Expect either StringImm naming the "
375	             "resource_handle var from interface API, or "
376	          << "zero; got " << op->args[5];
377	    }
378	  }
379	  return {func_name, num_args, "NULL"};
380	}
381	
382	void CodeGenTileLangCPP::VisitExpr_(const CallNode *op,
383	                                    std::ostream &os) { // NOLINT(*)
384	  if (op->op.same_as(builtin::tvm_stack_alloca())) {
385	    std::string stack_name = name_supply_->FreshName("stack");
386	    const std::string &type = op->args[0].as<StringImmNode>()->value;
387	    const IntImmNode *num = op->args[1].as<IntImmNode>();
388	    ICHECK(num != nullptr);
389	    static_assert(alignof(TVMFFIAny) % alignof(DLTensor) == 0, "invariant");
390	    size_t unit = sizeof(TVMFFIAny);
391	    size_t size = 0;
392	    if (type == "shape") {
393	      size = (num->value * sizeof(runtime::tvm_index_t) + unit - 1) / unit;
394	    } else if (type == "arg_value") {
395	      size = (num->value * sizeof(TVMFFIAny) + unit - 1) / unit;
396	    } else if (type == "arg_tcode") {
397	      size = (num->value * sizeof(int) + unit - 1) / unit;
398	    } else if (type == "array") {
399	      size = (num->value * sizeof(DLTensor) + unit - 1) / unit;
400	    } else {
401	      LOG(FATAL) << "Unknown stack alloca type " << type;
402	    }
403	    this->PrintIndent();
404	    this->stream << "TVMFFIAny " << stack_name << "[" << size << "];\n";
405	    os << stack_name;
406	  } else if (op->op.same_as(builtin::tvm_call_packed_lowered())) {
407	    auto function_info = GetFunctionInfo(op, false /* has_resource_handle */);
408	    std::string func_name_packed = GetPackedName(op);
409	    this->PrintGetFuncFromBackend(function_info.func_name, func_name_packed);
410	    this->PrintFuncCall(func_name_packed, function_info.num_args);
411	  } else if (op->op.same_as(builtin::tvm_call_cpacked_lowered())) {
412	    auto function_info = GetFunctionInfo(op, true /* has_resource_handle */);
413	    this->PrintFuncCallC(function_info.func_name, function_info.num_args,
414	                         function_info.resource_handle_name);
415	  } else if (op->op.same_as(builtin::tvm_throw_last_error())) {
416	    this->PrintIndent();
417	    this->stream << "return -1;\n";
418	  } else {
419	    CodeGenC::VisitExpr_(op, os);
420	  }
421	}
422	
423	void CodeGenTileLangCPP::VisitStmt_(const AssertStmtNode *op) { // NOLINT(*)
424	  if (emit_asserts_) {
425	    std::string cond = PrintExpr(op->condition);
426	    PrintIndent();
427	    stream << "if (!(" << cond << ")) {\n";
428	    int assert_if_scope = this->BeginScope();
429	    PrintIndent();
430	    stream << "TVMAPISetLastError(\"" << op->message.as<StringImmNode>()->value
431	           << "\");\n";
432	    PrintIndent();
433	    stream << "return -1;\n";
434	    this->EndScope(assert_if_scope);
435	    PrintIndent();
436	    stream << "}\n";
437	  }
438	  this->PrintStmt(op->body);
439	}
440	
441	void CodeGenTileLangCPP::VisitStmt_(const AllocateNode *op) {
442	  ICHECK(!is_zero(op->condition));
443	  std::string vid = AllocVarID(op->buffer_var.get());
444	
445	  this->PrintIndent();
446	  std::string scope = GetPtrStorageScope(op->buffer_var);
447	
448	  PrintType(op->dtype, stream);
449	  size_t constant_size = op->ConstantAllocationSize();
450	  ICHECK_GT(constant_size, 0)
451	      << "Can only handle constant size stack allocation for now";
452	
453	  stream << ' ' << vid << '[' << constant_size << "];\n";
454	
455	  RegisterHandleType(op->buffer_var.get(), op->dtype);
456	  this->PrintStmt(op->body);
457	}
458	
459	void CodeGenTileLangCPP::VisitExpr_(const MinNode *op,
460	                                    std::ostream &os) { // NOLINT(*)
461	  PrintTernaryCondExpr(op, "<", os);
462	}
463	
464	void CodeGenTileLangCPP::VisitExpr_(const MaxNode *op,
465	                                    std::ostream &os) { // NOLINT(*)
466	  PrintTernaryCondExpr(op, ">", os);
467	}
468	
469	template <typename T>
470	inline void
471	CodeGenTileLangCPP::PrintTernaryCondExpr(const T *op, const char *compare,
472	                                         std::ostream &os) { // NOLINT(*)
473	  std::ostringstream temp_a;
474	  VisitExpr(op->a, temp_a);
475	  std::string a_id = SSAGetID(temp_a.str(), op->a.dtype());
476	  std::ostringstream temp_b;
477	  VisitExpr(op->b, temp_b);
478	  std::string b_id = SSAGetID(temp_b.str(), op->b.dtype());
479	
480	  os << "((" << a_id << ") " << compare << " (" << b_id << ") "
481	     << "? (" << a_id << ") : (" << b_id << "))";
